insert into comment_log (id, workspace_id, day, author, segment, url, mode, text, reply, source, created_at, prospect_id, author_url, post_text) values
  ('0de30005-0000-4000-8000-000000000001', '0de30000-0000-4000-8000-000000000001', current_date - 27, 'Joanna Wells', 'C', 'https://linkedin.example.com/feed/update/demo-1001', 'Operator lens', 'In my view the hard part is reconciliation, not speed. Instant payouts help only when the remittance data arrives with the money. Which reference fields are you asking acquirers to carry through?', false, 'extension', current_date - 27 + time '09:38', null, 'https://linkedin.example.com/in/joannawells', 'Our first quarter on instant payments: volumes, exceptions and what we changed in operations.'),
  ('0de30005-0000-4000-8000-000000000002', '0de30000-0000-4000-8000-000000000001', current_date - 27, 'Mohammed Al Amri', 'E', 'https://linkedin.example.com/feed/update/demo-1002', 'Question', 'Agree on the corridor point. The cost on UK to GCC transfers is mostly in the FX spread and the correspondent hop, not the fee on the invoice. Are you seeing banks quote the spread separately yet?', false, 'extension', current_date - 27 + time '10:55', null, 'https://linkedin.example.com/in/mohammedalamri', 'The new consultation on instant payment scheme rules is out. Here is what participants are asked to comment on.'),
  ('0de30005-0000-4000-8000-000000000003', '0de30000-0000-4000-8000-000000000001', current_date - 27, 'Mohammed Al Amri', 'A', 'https://linkedin.example.com/feed/update/demo-1003', 'Data point', 'This matches what operations teams run into. Real-time rails move the cut-off problem to exception handling, so the team on call at 2am matters more than the batch job did. Who owns exceptions in your setup?', false, 'extension', current_date - 27 + time '11:12', null, 'https://linkedin.example.com/in/mohammedalamri', 'Cross-border payments between the UK and the Gulf are getting cheaper, but not evenly. A short thread on where the cost sits.'),
  ('0de30005-0000-4000-8000-000000000004', '0de30000-0000-4000-8000-000000000001', current_date - 27, 'Karim Saleh', 'B', 'https://linkedin.example.com/feed/update/demo-1004', 'Board lens', 'The consultation reads as a push toward common scheme rules, which should lower onboarding effort for smaller merchants. The open question is dispute timing on instant payments. Do you expect a separate window for those?', false, 'extension', current_date - 27 + time '12:29', null, 'https://linkedin.example.com/in/karimsaleh', 'Treasury teams are rethinking daily liquidity now that payouts arrive the same day.'),
  ('0de30005-0000-4000-8000-000000000005', '0de30000-0000-4000-8000-000000000001', current_date - 27, 'Lina Mourad', 'B', 'https://linkedin.example.com/feed/update/demo-1005', 'Partner lens', 'Good point on treasury. Once settlement is daily, the forecast moves from weekly buckets to daily ones, and most treasury tools are not set up for that. What are you using for the daily view?', true, 'extension', current_date - 27 + time '13:46', null, 'https://linkedin.example.com/in/linamourad', 'Card settlement still takes two to three days for most merchants in the region. We looked at what that costs a mid-size retailer.'),
  ('0de30005-0000-4000-8000-000000000006', '0de30000-0000-4000-8000-000000000001', current_date - 26, 'Joanna Wells', 'C', 'https://linkedin.example.com/feed/update/demo-1006', 'Agree and add', 'I think partners decide how fast this spreads. Merchants rarely switch acquirer for speed alone, but they do when their platform offers it by default. Which platforms are moving first in your market?', false, 'extension', current_date - 26 + time '09:45', null, 'https://linkedin.example.com/in/joannawells', 'Our first quarter on instant payments: volumes, exceptions and what we changed in operations.'),
  ('0de30005-0000-4000-8000-000000000007', '0de30000-0000-4000-8000-000000000001', current_date - 26, 'Vikram Desai', 'C', 'https://linkedin.example.com/feed/update/demo-1007', 'Operator lens', 'In my perspective the controls story is what boards will ask about. Faster money means less time to stop a bad payout, so limits and holds need to be designed in early. How are you setting the first limits?', false, 'extension', current_date - 26 + time '10:02', null, 'https://linkedin.example.com/in/vikramdesai', 'The new consultation on instant payment scheme rules is out. Here is what participants are asked to comment on.'),
  ('0de30005-0000-4000-8000-000000000008', '0de30000-0000-4000-8000-000000000001', current_date - 26, 'Karim Saleh', 'B', 'https://linkedin.example.com/feed/update/demo-1008', 'Question', 'One number worth adding: if card sales settle in one day instead of three, a merchant doing a steady volume frees roughly two days of sales in cash. That is the part finance directors understand quickly.', false, 'extension', current_date - 26 + time '11:19', null, 'https://linkedin.example.com/in/karimsaleh', 'Cross-border payments between the UK and the Gulf are getting cheaper, but not evenly. A short thread on where the cost sits.'),
  ('0de30005-0000-4000-8000-000000000009', '0de30000-0000-4000-8000-000000000001', current_date - 26, 'Mohammed Al Amri', 'A', 'https://linkedin.example.com/feed/update/demo-1009', 'Data point', 'Agree with the direction. The schemes that work tend to publish clear service levels for participants, so merchants can see who is slow. Do you think participants here will publish theirs?', false, 'extension', current_date - 26 + time '12:36', null, 'https://linkedin.example.com/in/mohammedalamri', 'Treasury teams are rethinking daily liquidity now that payouts arrive the same day.'),
  ('0de30005-0000-4000-8000-00000000000a', '0de30000-0000-4000-8000-000000000001', current_date - 26, 'Huda Al Rais', 'C', 'https://linkedin.example.com/feed/update/demo-1010', 'Board lens', 'I think the settlement window is the part most merchants feel first. A hotel group paid two days later is funding its own card volume, and that cost rarely shows up in the pricing talk. How are you measuring the working capital effect on your side?', true, 'extension', current_date - 26 + time '13:53', null, 'https://linkedin.example.com/in/hudaalrais', 'Card settlement still takes two to three days for most merchants in the region. We looked at what that costs a mid-size retailer.'),
