insert into saved_drafts (id, workspace_id, kind, text, author, post_url, style, post_type, human, impact, source, created_by, created_at) values
  ('0de30016-0000-4000-8000-000000000001', '0de30000-0000-4000-8000-000000000001', 'comment', 'I think the settlement window is the part most merchants feel first. A hotel group paid two days later is funding its own card volume, and that cost rarely shows up in the pricing talk. How are you measuring the working capital effect on your side?', 'Samir Nassar', 'https://linkedin.example.com/feed/update/demo-d1', 'Operator lens', 'Opinion', 88, 82, 'extension', pg_temp.demo_owner(), current_date - 1 + time '10:15'),
  ('0de30016-0000-4000-8000-000000000002', '0de30000-0000-4000-8000-000000000001', 'comment', 'The consultation reads as a push toward common scheme rules, which should lower onboarding effort for smaller merchants. The open question is dispute timing on instant payments. Do you expect a separate window for those?', 'Dana Al Khalifa', 'https://linkedin.example.com/feed/update/demo-d2', 'Question', 'Announcement', 84, 86, 'extension', pg_temp.demo_owner(), current_date - 3 + time '10:15'),
  ('0de30016-0000-4000-8000-000000000003', '0de30000-0000-4000-8000-000000000001', 'comment', 'One number worth adding: if card sales settle in one day instead of three, a merchant doing a steady volume frees roughly two days of sales in cash. That is the part finance directors understand quickly.', 'Grace Mwangi', 'https://linkedin.example.com/feed/update/demo-d3', 'Data point', 'Data post', 81, 79, 'extension', pg_temp.demo_owner(), current_date - 5 + time '10:15');
insert into posts (id, workspace_id, title, format, publish_date, status, topic, resource, draft, url, impressions, reactions, comments, created_at, pillar, planned_time, channel, hook, requested_by, requested_at, decided_by, decided_at, decision, angle, source_kind, discovery) values
  ('0de30006-0000-4000-8000-000000000001', '0de30000-0000-4000-8000-000000000001', 'Why two-day settlement is a cash-flow tax on GCC merchants', 'Text post', current_date - 26, 'Posted', 'Instant settlement', '', 'Why two-day settlement is a cash-flow tax on GCC merchants
insert into templates (id, workspace_id, name, kind, body, sort) values
  ('0de30007-0000-4000-8000-000000000001', '0de30000-0000-4000-8000-000000000001', 'Connection note after two comments', 'note', 'Hi {first}, I have enjoyed your posts on {topic}. I run operations at Northgate Payments and write about settlement in the GCC. Would be good to connect.', 0),
  ('0de30007-0000-4000-8000-000000000002', '0de30000-0000-4000-8000-000000000001', 'Connection note for a corridor contact', 'note', 'Hi {first}, I work on the UK to GCC corridor at Northgate Payments and saw your note on FX spreads. Happy to connect and compare notes.', 1),
  ('0de30007-0000-4000-8000-000000000003', '0de30000-0000-4000-8000-000000000001', 'First message after accepting', 'message', 'Thanks for connecting, {first}. Out of interest, how long does card settlement take for your merchants today? We see a wide range across the region.', 2),
  ('0de30007-0000-4000-8000-000000000004', '0de30000-0000-4000-8000-000000000001', 'Follow-up on settlement timing', 'message', 'Hi {first}, following up on settlement timing. I put together a short checklist we use when a merchant moves to same-day settlement. Would it be useful?', 3),
  ('0de30007-0000-4000-8000-000000000005', '0de30000-0000-4000-8000-000000000001', 'Resource reply: settlement checklist', 'resource', 'Here is the checklist, {first}. Sections 2 and 3 cover reconciliation data and exception handling, which is where most of the work is.', 4),
  ('0de30007-0000-4000-8000-000000000006', '0de30000-0000-4000-8000-000000000001', 'Call offer after the resource', 'call', 'If it helps, I am happy to walk your team through how we run same-day payouts. Twenty minutes next week?', 5),
  ('0de30007-0000-4000-8000-000000000007', '0de30000-0000-4000-8000-000000000001', 'Reply to a comment on my post', 'reply', 'Thank you, {first}. On your point about {point}: in our experience the exceptions team decides it, more than the rails do.', 6);
insert into notes (id, workspace_id, kind, title, body, sort, created_at, created_by) values
  ('0de30008-0000-4000-8000-000000000001', '0de30000-0000-4000-8000-000000000001', 'strategy', 'Goal for the quarter', 'Be the operator people quote on same-day settlement in the GCC. Ten target accounts in conversation and three calls booked by the end of the quarter.', 0, current_date - 27 + time '10:00', pg_temp.demo_owner()),
  ('0de30008-0000-4000-8000-000000000002', '0de30000-0000-4000-8000-000000000001', 'strategy', 'Who we target', 'Heads of payments, settlement and treasury at GCC banks and PSPs; finance directors at hospitality and retail groups; the UK side of the UK to GCC corridor.', 1, current_date - 27 + time '10:05', pg_temp.demo_owner()),
  ('0de30008-0000-4000-8000-000000000003', '0de30000-0000-4000-8000-000000000001', 'strategy', 'What Layla posts about', 'Instant settlement, cross-border corridors, payments operations, regulation in practice and agentic commerce. Two to three posts a week, one carousel.', 2, current_date - 27 + time '10:10', pg_temp.demo_owner()),
  ('0de30008-0000-4000-8000-000000000004', '0de30000-0000-4000-8000-000000000001', 'strategy', 'How we engage', 'Five thoughtful comments a day on target accounts and industry voices. Request after two comments; first message on settlement timing; offer the checklist, then a call.', 3, current_date - 27 + time '10:15', pg_temp.demo_owner()),
  ('0de30008-0000-4000-8000-00000000000a', '0de30000-0000-4000-8000-000000000001', 'note', 'Call prep: Qasr Digital Bank', 'Rania asked about dispute windows on instant payments and how we staff exceptions overnight. Bring the reconciliation numbers.', 0, current_date - 1 + time '17:20', pg_temp.demo_owner()),
  ('0de30008-0000-4000-8000-00000000000b', '0de30000-0000-4000-8000-000000000001', 'note', 'Post ideas from the hotel finance calls', 'Finance teams care about next-morning money more than same-hour money. Peak season volumes break batch processes first.', 0, current_date - 8 + time '12:05', pg_temp.demo_owner());
insert into threads (id, workspace_id, ref_table, ref_id, author, author_email, body, created_at) values
  ('0de30015-0000-4000-8000-000000000001', '0de30000-0000-4000-8000-000000000001', 'prospects', '0de30002-0000-4000-8000-000000000001', pg_temp.demo_owner(), current_setting('prax.demo_owner_email'), 'Call booked for Thursday. She wants to see the reconciliation report format.', current_date - 1 + time '16:45'),
  ('0de30015-0000-4000-8000-000000000002', '0de30000-0000-4000-8000-000000000001', 'prospects', '0de30002-0000-4000-8000-000000000002', pg_temp.demo_owner(), current_setting('prax.demo_owner_email'), 'Harbourline is reviewing its Gulf corridor partner next year. Keep the conversation on FX spreads.', current_date - 4 + time '11:10'),
  ('0de30015-0000-4000-8000-000000000003', '0de30000-0000-4000-8000-000000000001', 'prospects', '0de30002-0000-4000-8000-000000000006', pg_temp.demo_owner(), current_setting('prax.demo_owner_email'), 'Signed. Kick-off with their operations team is being scheduled.', current_date - 2 + time '14:30');
