  ('0de30000-0000-4000-8000-000000000001', '{"stances":["Settlement speed is a merchant cash-flow issue before it is a technology issue.","Instant payments need operations, treasury and compliance designed together."],"proofs":[{"text":"Moved card settlement from two days to same day for UAE and Saudi merchants (demo figure)","cleared":true}],"numbers":[{"value":"4,000 merchants","context":"Northgate Payments merchants (demo figure)"}],"clients":[]}', '{"name":"Settled","cadence":"fortnightly","weekday":2}');
