insert into network_posts (workspace_id, kind, key, day, url, text) values
  ('0de30000-0000-4000-8000-000000000001', 'post', 'https://linkedin.example.com/posts/laylahaddad-demo-1', current_date - 26, 'https://linkedin.example.com/posts/laylahaddad-demo-1', 'Why two-day settlement is a cash-flow tax on GCC merchants. Card settlement still takes two to three days for most merchants in the region. We looked at what that costs a mid-size retailer.'),
  ('0de30000-0000-4000-8000-000000000001', 'post', 'https://linkedin.example.com/posts/laylahaddad-demo-2', current_date - 23, 'https://linkedin.example.com/posts/laylahaddad-demo-2', 'Five numbers from our first year of same-day settlement. Our first quarter on instant payments: volumes, exceptions and what we changed in operations.'),
  ('0de30000-0000-4000-8000-000000000001', 'post', 'https://linkedin.example.com/posts/laylahaddad-demo-3', current_date - 20, 'https://linkedin.example.com/posts/laylahaddad-demo-3', 'What hotel finance teams told me about card settlement. The new consultation on instant payment scheme rules is out. Here is what participants are asked to comment on.'),
  ('0de30000-0000-4000-8000-000000000001', 'post', 'https://linkedin.example.com/posts/laylahaddad-demo-4', current_date - 16, 'https://linkedin.example.com/posts/laylahaddad-demo-4', 'The UK to GCC corridor: where the cost actually sits. Cross-border payments between the UK and the Gulf are getting cheaper, but not evenly. A short thread on where the cost sits.'),
  ('0de30000-0000-4000-8000-000000000001', 'post', 'https://linkedin.example.com/posts/laylahaddad-demo-5', current_date - 13, 'https://linkedin.example.com/posts/laylahaddad-demo-5', 'Instant payments will not fix reconciliation on their own. Treasury teams are rethinking daily liquidity now that payouts arrive the same day.'),
  ('0de30000-0000-4000-8000-000000000001', 'comment', 'https://linkedin.example.com/feed/update/demo-c1|0', current_date - 14, 'https://linkedin.example.com/feed/update/demo-c1', 'Settlement speed matters most for hospitality and travel merchants.'),
  ('0de30000-0000-4000-8000-000000000001', 'comment', 'https://linkedin.example.com/feed/update/demo-c2|1', current_date - 17, 'https://linkedin.example.com/feed/update/demo-c2', 'Reconciliation data is the real bottleneck for instant payouts.'),
  ('0de30000-0000-4000-8000-000000000001', 'comment', 'https://linkedin.example.com/feed/update/demo-c3|2', current_date - 20, 'https://linkedin.example.com/feed/update/demo-c3', 'UK to GCC corridors: the spread is where the cost sits.');
