MSc, Finance', '{"name":"Layla Haddad","headline":"Chief Operating Officer at Northgate Payments | Instant settlement and cross-border payments for GCC merchants and banks","location":"Dubai, United Arab Emirates","about":"I help merchants and banks in the GCC get paid the same day. As Chief Operating Officer of Northgate Payments I run settlement, payment operations and merchant acquiring for more than 4,000 merchants in the UAE, Saudi Arabia and the UK, including the UK to GCC corridor for cross-border payments. Over 15 years in payments I have learned that instant payments only work when operations, treasury and compliance are designed together. At Northgate we moved card settlement from two days to same day, cut reconciliation breaks by 40 percent and opened open banking payouts for marketplace merchants. Before Northgate I spent five years at Crescent Card Services as Head of Payment Operations, running settlement and reconciliation for a regional acquirer, and three years in treasury operations at a UK bank. I write every week about settlement speed, cross-border corridors, payment operations and how regulation turns into day-to-day controls. Stablecoins and agentic payments come up too, always from the operator''s side. If you run payments at a bank, PSP or large merchant in the GCC or the UK, send me a message. I am always happy to compare notes on settlement.","skills":["Instant payments","Settlement","Cross-border payments"],"languages":["Arabic (Native or Bilingual)","English (Full Professional)"],"certifications":[],"experience":[{"company":"Northgate Payments","title":"Chief Operating Officer","dates":"March 2021 - Present (5 years 8 months)","current":true,"description":"I lead payment operations, risk, compliance and merchant support. We moved settlement from two days to same day for card merchants in the UAE and Saudi Arabia, launched the UK to GCC payout corridor in 2024 and cut reconciliation breaks by 40 percent. I run a team of 60 across Dubai, Riyadh and London and own the treasury and liquidity model behind same-day payouts."},{"company":"Crescent Card Services","title":"Head of Payment Operations","dates":"June 2016 - February 2021 (4 years 9 months)","current":false,"description":"Ran settlement and reconciliation for a regional acquirer with 12,000 merchants. Built the exceptions team and the first daily settlement report for merchant acquiring."},{"company":"Harbour Street Bank","title":"Treasury Operations Manager","dates":"September 2013 - May 2016 (2 years 9 months)","current":false,"description":"Treasury operations and cross-border payments for corporate clients."}],"education":["Westbridge University","MSc, Finance"],"url":"","email":"layla.haddad@northgate-payments.example.com","website":"northgate-payments.example.com"}', '{"score":97,"areas":[{"area":"Headline","points":20,"max":20},{"area":"About","points":25,"max":25},{"area":"Topics","points":20,"max":20},{"area":"Experience","points":20,"max":20},{"area":"Skills","points":10,"max":10},{"area":"Contact","points":2,"max":5}],"checks":[{"id":"hl-len","area":"Headline","label":"Headline is 60 to 220 characters","pass":true,"points":5,"max":5,"fix":"It is 120 characters. Use the space: role, the two topics you want to be known for, and who you help."},{"id":"hl-topics","area":"Headline","label":"Headline names at least two target topics","pass":true,"points":8,"max":8,"fix":"Found settlement, cross-border payments, GCC. Put two of: instant payments, settlement, cross-border payments, payment operations, merchant acquiring."},{"id":"hl-role","area":"Headline","label":"Headline states a role or seniority","pass":true,"points":3,"max":3,"fix":"Lead with the role a buyer recognises, e.g. Co-Founder & COO."},{"id":"hl-who","area":"Headline","label":"Headline says who you help or what you build","pass":true,"points":4,"max":4,"fix":"Add who it is for: \"for banks and payment firms\" reads clearer than a list of nouns."},{"id":"ab-present","area":"About","label":"About section exists","pass":true,"points":5,"max":5,"fix":"Write an About. It is the longest text LinkedIn reads to decide what you are an authority on."},{"id":"ab-len","area":"About","label":"About is 1,000 to 2,600 characters","pass":true,"points":5,"max":5,"fix":"It is 1166 characters. Aim for roughly 1,500: enough proof, still readable."},{"id":"ab-early","area":"About","label":"A target topic appears in the first 220 characters","pass":true,"points":6,"max":6,"fix":"Only the first lines show before \"see more\". Name the core topic there."},{"id":"ab-proof","area":"About","label":"About carries numbers or named proof","pass":true,"points":5,"max":5,"fix":"Add counted proof: years, deployments, markets, clients, volumes."},{"id":"ab-cta","area":"About","label":"About ends with a way to reach you","pass":true,"points":4,"max":4,"fix":"Close with one plain line on how to start a conversation."},{"id":"tp-cover","area":"Topics","label":"Profile covers at least 60% of target topics","pass":true,"points":12,"max":12,"fix":"Covers 100%. Missing: none."},{"id":"tp-focus","area":"Topics","label":"Headline and About agree on the same topics","pass":true,"points":8,"max":8,"fix":"Repeat the headline topics in the About so the profile reads as one specialism."},{"id":"ex-cur","area":"Experience","label":"Current role has a description of 300+ characters","pass":true,"points":7,"max":7,"fix":"Describe the current role: what you run, for whom, and results."},{"id":"ex-num","area":"Experience","label":"Current role shows quantified outcomes","pass":true,"points":5,"max":5,"fix":"Add at least one number to the current role."},{"id":"ex-topics","area":"Experience","label":"Current role mentions target topics","pass":true,"points":5,"max":5,"fix":"Tie the current role to the topics you post about."},{"id":"ex-depth","area":"Experience","label":"At least two roles listed","pass":true,"points":3,"max":3,"fix":"List earlier roles; tenure is part of credibility."},{"id":"sk-present","area":"Skills","label":"Skills are listed","pass":true,"points":4,"max":4,"fix":"Add at least three skills (the PDF shows your top three)."},{"id":"sk-topics","area":"Skills","label":"Top skills match target topics","pass":true,"points":6,"max":6,"fix":"Pin skills that match your topics as the top three."},{"id":"ct-url","area":"Contact","label":"Custom profile URL","pass":false,"points":0,"max":3,"fix":"Set a clean custom URL (no trailing numbers)."},{"id":"ct-web","area":"Contact","label":"Website or email listed","pass":true,"points":2,"max":2,"fix":"Add the company site to Contact info."}],"manual":{},"roadmap":{"m1-headline":true,"m1-about":true,"m1-skills":true}}', 97, pg_temp.demo_owner(), current_date - 2 + time '15:10');

-- snapshots: LinkedIn reach

alter table comment_log enable trigger comment_logged;

-- InMail tasks exist on weekdays only (as Today builds them), so weekend ones go, with their feed rows.
delete from activity where workspace_id = '0de30000-0000-4000-8000-000000000001' and kind = 'inmail' and extract(isodow from at) > 5;
delete from daily_items where workspace_id = '0de30000-0000-4000-8000-000000000001' and kind = 'inmail' and extract(isodow from day) > 5;

commit;

select 'ok' as status, (select name from workspaces where id = '0de30000-0000-4000-8000-000000000001') as profile,
  (select count(*) from prospects where workspace_id = '0de30000-0000-4000-8000-000000000001') as prospects,
  (select email from members m join auth.users u on u.id = m.user_id where m.workspace_id = '0de30000-0000-4000-8000-000000000001' and m.role = 'owner' limit 1) as owner;

